#!/usr/bin/env python3
"""Frozen per-byte tamper verdicts over the staged artifact envelopes.

Every cell tampers one envelope one way — a single-bit flip at one position of the sealed audio or result artifact, or a truncation at one length — and freezes the typed refusal the read boundary must return (``StagedArtifactInvalid`` with its envelope or authentication message). A tampered byte can never read, and a cell that fails means an envelope mutation silently decrypted.

Failure-Class: FC-persist-socket-transport-loss-discards-completed-gpu-results
"""

import hashlib
import json

import pytest

from google.api_core.exceptions import NotFound

from utils.batch_pipeline.artifacts import (
    AUDIO_LIMIT,
    RESULT_LIMIT,
    StagedArtifactInvalid,
    ArtifactStore,
    ProtectionContext,
)
from utils.batch_pipeline.contracts import Priority, WorkItem
from utils.batch_pipeline.source_audio import MAGIC

AUDIO_BODY = bytes(((index * 7 + 3) % 251) for index in range(1024))
RESULT_BODY = bytes(((index * 11 + 5) % 251) for index in range(200))
OWNER = 'synthetic-owner'
OTHER_OWNER = 'synthetic-owner-b'
KEYS = {OWNER: b'a' * 32, OTHER_OWNER: b'b' * 32}


class FakeObjectClient:
    """Minimal generation-pinned object store: no network, no SDK."""

    def __init__(self):
        self.objects = {}
        self.uploads = 0
        self.deletes = 0

    def bucket(self, name):
        return self

    def reload(self, **kwargs):
        pass

    @property
    def soft_delete_policy(self):
        class _Policy:
            retention_duration_seconds = 0
            default_event_based_hold = False
            retention_period = None

        return _Policy()

    @property
    def default_event_based_hold(self):
        return False

    @property
    def retention_period(self):
        return None

    def blob(self, name, generation=None):
        client = self

        class Blob:
            def __init__(self):
                self.generation = generation
                self.size = None
                self.chunk_size = None

            def upload_from_file(self, stream, **kw):
                body = stream.read()
                client.uploads += 1
                self.generation = client.uploads
                client.objects[name] = (self.generation, body)

            def reload(self, **kw):
                if name not in client.objects:
                    raise NotFound('synthetic absent object')
                stored_generation, body = client.objects[name]
                self.generation = stored_generation
                if kw.get('if_generation_match', stored_generation) != stored_generation:
                    raise ValueError('generation mismatch')
                self.size = len(body)

            def download_as_bytes(self, **kw):
                stored_generation, body = client.objects[name]
                if kw.get('if_generation_match') != stored_generation:
                    raise ValueError('generation mismatch')
                return body

            def delete(self, **kw):
                client.deletes += 1
                client.objects.pop(name, None)

        return Blob()


class FakeShadowResult:
    def __init__(self):
        self.seen = []

    def __call__(self, item, payload):
        self.seen.append((item.segment_id, payload))


def item(owner=OWNER, **overrides):
    values = dict(
        segment_id='synthetic-segment',
        owner_id=owner,
        capture_at=100.0,
        audio_uri='pending',
        duration_seconds=1.0,
        priority=Priority.FRESH,
        privacy_generation=0,
    )
    values.update(overrides)
    return WorkItem(**values)


def make_store(owner=OWNER, level='enhanced', generation=0, shadow_result=None, authorize=None):
    client = FakeObjectClient()
    state = {'context': ProtectionContext(level, generation), 'registered': []}
    store = ArtifactStore(
        client,
        bucket='synthetic-batch-bucket',
        namespace='batch_pipeline_test_grid',
        authorize=authorize or (lambda i: state['context']),
        key_for_owner=lambda uid: KEYS.get(uid, b'c' * 32),
        register_artifact=lambda *args: state['registered'].append(args),
        shadow_result=shadow_result,
    )
    return store, client, state


def stage(kind, *, owner=OWNER, level='enhanced', generation=0, body=None):
    store, client, state = make_store(owner=owner, level=level, generation=generation)
    unit = item(owner=owner)
    payload = AUDIO_BODY if kind == 'audio' else RESULT_BODY if body is None else body
    if kind == 'audio':
        uri = store.stage_audio(unit, payload)
    else:
        uri = store.persist_result(unit, {'words': []})
    return store, client, state, unit, uri


def _only_name(client):
    assert len(client.objects) == 1
    return next(iter(client.objects))


def _expect_tamper_refused(kind, mode, arg, mask, message):
    store, client, _state, unit, uri = stage(kind)
    name = _only_name(client)
    generation, body = client.objects[name]
    if mode == 'flip':
        mutated = body[:arg] + bytes([body[arg] ^ mask]) + body[arg + 1 :]
    else:
        mutated = body[:arg]
    client.objects[name] = (generation, mutated)
    with pytest.raises(StagedArtifactInvalid) as info:
        store._read(unit, uri, kind, AUDIO_LIMIT if kind == 'audio' else RESULT_LIMIT)
    assert str(info.value) == message


def _expect_read_ok(kind):
    store, client, _state, unit, uri = stage(kind)
    payload = store._read(unit, uri, kind, AUDIO_LIMIT if kind == 'audio' else RESULT_LIMIT)
    return payload


